// Decision-first — unit tests. NO network, NO model.
//
// Every topic opens with the DECISION and a one-line WHY, and the sourced depth sits
// one tap behind it. These pin the inversion so it cannot decay back into an essay:
// the budget that keeps the default view readable in about five seconds, the voice
// rules that apply to every line Kristy speaks, and the claim lock, which did NOT
// widen to accommodate two new fields.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { nonEmpty } from './testGuards.js';

import { perimeterKb, questionEntries, publicEntry, sanitizeForModel, buildAnswerInput, sectionIndex } from './perimeter.js';

const entries = nonEmpty(questionEntries(perimeterKb.entries || []), 'questionEntries');

/* ── Every topic leads with a call ─────────────────────────────────────────────── */

test('every entry carries a decision and a one-line why', () => {
  for (const e of entries) {
    assert.ok(typeof e.decision === 'string' && e.decision.trim(), `${e.id} has no decision`);
    assert.ok(typeof e.why === 'string' && e.why.trim(), `${e.id} has no why`);
  }
});

test('the decision is glanceable and the why is one line', () => {
  // The word budget IS the feature. A default view longer than this is the essay
  // coming back in, and in a store nobody reads the essay.
  for (const e of entries) {
    assert.ok(e.decision.length <= 90, `${e.id}: decision is ${e.decision.length} chars — too long to glance`);
    assert.ok(e.why.length <= 120, `${e.id}: why is ${e.why.length} chars — that is a paragraph`);
    // A call, not a discussion. Two sentences at most.
    const sentences = e.decision.split(/[.!?]+\s/).filter(Boolean).length;
    assert.ok(sentences <= 3, `${e.id}: decision runs ${sentences} sentences`);
  }
});

test('the default view stays inside the five-second budget', () => {
  // What renders before any tap: decision + why + the first three buying tips.
  const WORDS = (s) => String(s).trim().split(/\s+/).length;
  for (const e of entries) {
    const above = WORDS(e.decision) + WORDS(e.why) + (e.buying_tips || []).slice(0, 3).reduce((n, t) => n + WORDS(t), 0);
    assert.ok(above <= 90, `${e.id}: ${above} words above the fold`);
  }
});

/* ── The voice, on the two new lines ───────────────────────────────────────────── */

test('no first person anywhere in a decision or a why (VOICE_SPEC)', () => {
  // Kristy is a standard, not a person narrating. The decision is the flattest,
  // most quotable copy in the product, so it is the easiest place for an "I'd" to
  // creep back in.
  const FIRST_PERSON = /\b(i|i'?m|i'?ll|i'?d|i'?ve|me|my|mine|myself|let me)\b/i;
  for (const e of entries) {
    assert.doesNotMatch(e.decision, FIRST_PERSON, `${e.id} decision speaks in first person`);
    assert.doesNotMatch(e.why, FIRST_PERSON, `${e.id} why speaks in first person`);
  }
});

test('no em-dash asides, and no price, in a decision or a why', () => {
  for (const e of entries) {
    for (const [field, text] of [['decision', e.decision], ['why', e.why]]) {
      assert.doesNotMatch(text, /—/, `${e.id} ${field} uses an em-dash aside`);
      assert.doesNotMatch(text, /[$£€]|\bdollars?\b|\bcents?\b/i, `${e.id} ${field} quotes a price`);
    }
  }
});

test('no decision or why claims a health outcome, in either direction', () => {
  // The no-treatment rule is absolute and symmetric across the whole perimeter. It
  // applies with the most force here, because this is the line a shopper actually
  // reads and repeats.
  const OUTCOME =
    /\b(cures?|heals?|treats?|prevents?|reverses?|detox\w*|remed(y|ies)|immunity|diagnos\w*|causes? (cancer|disease|diabetes))\b/i;
  for (const e of entries) {
    assert.doesNotMatch(e.decision, OUTCOME, `${e.id} decision makes a health-outcome claim`);
    assert.doesNotMatch(e.why, OUTCOME, `${e.id} why makes a health-outcome claim`);
  }
});

test('a contested call still names the standard rather than asserting science', () => {
  // The tier chip renders beside the decision, so a reader always sees WHICH kind of
  // claim it is. On the entries where the distinction does the most work, the words
  // carry it too.
  for (const id of ['salmon_wild_vs_farmed', 'beef_grassfed_vs_grainfed']) {
    const e = entries.find((x) => x.id === id);
    assert.equal(e.evidence_tier, 'kristys_standard', `${id} should be a standard, not settled`);
    const text = `${e.decision} ${e.why}`.toLowerCase();
    assert.match(text, /whole-food standard|not settled science|preference|not a health verdict|not a claim/, `${id} states a contested call as fact`);
  }
});

/* ── The depth is demoted, not deleted ─────────────────────────────────────────── */

test('nothing was removed to make room for the decision', () => {
  // Re-ranking, not rewriting. Every field the card used to open with is still on
  // the entry, and still reaches the client — it just renders behind a tap.
  for (const e of entries) {
    for (const f of ['short_answer', 'detail', 'kristy_take', 'evidence_tier', 'sources', 'buying_tips']) {
      assert.ok(e[f] && e[f].length, `${e.id} lost ${f}`);
    }
  }
  const pub = publicEntry(entries.find((e) => e.id === 'salmon_wild_vs_farmed'));
  for (const f of ['decision', 'why', 'short_answer', 'detail', 'kristy_take', 'evidence_tier', 'evidence_framing', 'sources', 'buying_tips', 'labels_decoded', 'cart_pick']) {
    assert.ok(pub[f], `the full read is missing ${f}`);
  }
});

test('a browse row carries the decision, so the list itself answers', () => {
  // The section index used to show the short answer, which meant three lines of
  // background per row and a tap needed on every one to find the call.
  const topics = sectionIndex().flatMap((s) => [...s.topics, ...s.labelTopics]);
  assert.ok(topics.length > 0);
  for (const t of topics) {
    assert.ok(t.decision && t.decision.trim(), `${t.id} browses without its decision`);
    assert.ok(t.why && t.why.trim(), `${t.id} browses without its why`);
  }
});

/* ── The claim lock did not widen ──────────────────────────────────────────────── */

test('the model still sees exactly the seven allowed fields', () => {
  // decision and why are compressions of short_answer and kristy_take, which the
  // model already has. Passing them would buy nothing and widen the whitelist, so
  // they are deliberately absent.
  const ALLOWED = ['title', 'short_answer', 'detail', 'evidence_tier', 'buying_tips', 'labels_decoded', 'kristy_take'];
  const e = entries.find((x) => x.id === 'salmon_wild_vs_farmed');
  assert.deepEqual(Object.keys(sanitizeForModel(e)).sort(), [...ALLOWED].sort());
  assert.ok(!('decision' in sanitizeForModel(e)));
  assert.ok(!('why' in sanitizeForModel(e)));
});

test('a decision can never be minted by the model', () => {
  // Same guarantee cart_pick has: authored in the KB, never in the payload, so there
  // is no path by which a generated answer invents the call a shopper acts on.
  const e = entries.find((x) => x.id === 'beef_cuts_basics');
  const blob = JSON.stringify(
    buildAnswerInput({ question: 'which cut for stew', focuses: [], hardLines: [], constraints: [], entries: [e] })
  );
  assert.ok(!blob.includes(e.decision), 'the decision reached the model payload');
  assert.ok(!blob.includes(e.why), 'the why reached the model payload');
});

/* ── The decisions the spec called for, by name ────────────────────────────────── */

test('the three worked examples read as calls, not background', () => {
  // ⚠️ THIS TEST USED TO PIN THE CLIPPED FORM AND THAT WAS A STYLE, NOT THE RULE.
  // It asserted /^Chuck\./ and /^Wild\./ — the bare noun plus a full stop. What it was
  // protecting is real and is kept: the headline must open with the CALL, so a shopper
  // reading it alone knows what to reach for. What it also encoded, accidentally, was
  // the two-beat fragment register retired by VOICE_SPEC on 2026-08-23 ("state the fact,
  // do not rank it" / "the fact serves the direction"). A card may now say which one AND
  // why in one sentence, which the old regexes made impossible.
  //
  // So the assertion moved from the SHAPE to the PROPERTY, and it got stricter in the
  // process: the pick must still lead, and the headline must now also be a SENTENCE
  // rather than a fragment. A bare "Chuck." passed the old test and fails this one.
  const byId = (id) => entries.find((e) => e.id === id);
  const leads = (id, pick) => {
    const d = byId(id).decision;
    const words = d.trim().split(/\s+/);
    assert.ok(
      words.slice(0, 3).some((w) => w.replace(/[^A-Za-z-]/g, '').toLowerCase() === pick.toLowerCase()),
      `${id}: "${pick}" must lead the headline, not sit in the background — got: ${d}`
    );
    assert.ok(
      words.length >= 6,
      `${id}: the headline is a fragment (${words.length}w), not a sentence — got: ${d}`
    );
    return d;
  };
  // "Which cut for stew" → the cut, leading.
  leads('beef_cuts_basics', 'Chuck');
  // "Wild vs farmed salmon" → ONE verdict. This used to read "Wild if it is in reach.
  // Farmed or nothing, buy the farmed", which is two verdicts where the second cancels
  // the first. Under the one-verdict rule the fallback lives in watch_out, and it may
  // never climb back into the headline.
  leads('salmon_wild_vs_farmed', 'Wild');
  // "Is organic worth it" → where it earns it and where it does not.
  leads('organic_worth_it_by_type', 'Organic');
});
// EVERY CARD MUST BE REACHABLE BY THE QUESTIONS IT EXISTS TO ANSWER.
//
// This is the check that was missing, and its absence cost four duplicate cards. A curated
// card that exists, is correct, and cannot be retrieved is worse than no card: the shopper
// gets a generated near-copy, the corpus forks, and the bill arrives every time it is asked.
//
//   gen_picking_a_ripe_cantaloupe   `produce_ripeness_by_item` scored 3 against a `> 3` gate
//   gen_strawberry_freshness_check  `berries_picking` had no bare `strawberries`
//   gen_limp_lettuce_revival        `revive_greens` had no bare `lettuce`, `limp`, `wilted`
//   gen_picking_good_produce        the origin card and the hub both matched, neither won
//
// THE PHRASINGS LIVE ON THE CARD, in `asked_as`, not in a fixture here. A fixture is a
// second list that drifts from the first; on the entry, the phrasings are edited by whoever
// edits the card and reviewed in the same diff.
//
// AUTHOR THEM FROM THE QUESTION, NOT THE CARD'S OWN VOCABULARY. That is the entire defect
// this catches. `revive_greens` carried "limp lettuce" and "wilted lettuce" and a shopper
// typed "my lettuce went limp" — same words, different order, zero score. Write what someone
// would type before they have read anything: "my lettuce went limp", never "wilted greens
// revival".
//
// Run over the whole corpus on 2026-08-02 for the first time, this failed 75 of 243
// phrasings across 42 of 81 cards — so it was never a new-card problem. The largest block
// was the scope gate refusing label questions ("does no antibiotics mean anything"), which
// is why `isMeaningQuestion` exists.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { nonEmpty } from './testGuards.js';

import { scoreEntries, questionEntries } from './perimeter.js';
import { inScope } from './counterScope.js';
import { projectEntry } from './counterCards.js';

const MIN_PHRASINGS = 3;
// QUESTION ENTRIES ONLY. A pick (`kind: 'pick'`) carries no `asked_as` by rule — it is a
// sentence for a list row, not an answer to a question — and reachability through the ask
// is precisely what it must never have. Binding to the whole file would fail every pick
// for lacking phrasings, or worse, pass one that had them. Same predicate the ask reads.
const entries = nonEmpty(questionEntries(), 'perimeterKb question entries');

// The real gate, restated: `counterAskPipeline` admits on a score at or above the floor
// AND at least one alias hit. A phrasing that only clears one of those does not reach a
// shopper, so it does not count as reachable here either.
const admits = (top) => !!(top && top.score >= 2 && top.aliasScore > 0);

test('every card carries at least three authored question phrasings', () => {
  const missing = entries.filter((e) => !Array.isArray(e.asked_as) || e.asked_as.length < MIN_PHRASINGS);
  assert.deepEqual(
    missing.map((e) => `${e.id} (${e.asked_as?.length ?? 0})`),
    [],
    `every entry needs ${MIN_PHRASINGS}+ realistic phrasings in asked_as — a new card is not done until it can be found`
  );
});

test('a phrasing is a question someone would TYPE, not the card restating itself', () => {
  for (const e of entries) {
    for (const q of e.asked_as || []) {
      assert.equal(q, q.toLowerCase(), `${e.id}: "${q}" — phrasings are typed, so lowercase`);
      assert.ok(q.trim().split(/\s+/).length >= 2, `${e.id}: "${q}" is one word, which tests the alias and not the question`);
      // The title is the card's own vocabulary. A phrasing copied from it proves nothing:
      // the alias was almost certainly written from the same words.
      assert.notEqual(
        q.replace(/[^a-z0-9]/g, ''),
        String(e.title || '').toLowerCase().replace(/[^a-z0-9]/g, ''),
        `${e.id}: "${q}" is just the title — author from the QUESTION a shopper asks`
      );
    }
  }
});

test('EVERY authored phrasing is in scope', () => {
  const refused = [];
  for (const e of entries) {
    for (const q of e.asked_as || []) {
      const s = inScope(q);
      if (!s.ok) refused.push(`${e.id}: "${q}" → ${s.reason}`);
    }
  }
  assert.deepEqual(refused, [], 'the scope gate is refusing questions the corpus answers');
});

test('EVERY authored phrasing retrieves ITS OWN card, through the real gate', () => {
  const failures = [];
  for (const e of entries) {
    for (const q of e.asked_as || []) {
      if (!inScope(q).ok) continue; // reported by the test above
      const scored = scoreEntries(q, 3);
      const top = scored[0];
      if (!admits(top)) {
        failures.push(
          `${e.id}: "${q}" → ${top ? `${top.entry.id} scored ${top.score} on title words alone` : 'nothing matched'}`
        );
        continue;
      }
      if (top.entry.id !== e.id) {
        const self = scored.find((s) => s.entry.id === e.id)?.score ?? 0;
        failures.push(`${e.id}: "${q}" → ${top.entry.id} @${top.score}, self @${self}`);
      }
    }
  }
  assert.deepEqual(
    failures,
    [],
    'a card that cannot be retrieved by its own question regenerates as a duplicate. '
      + 'Add the phrase to the card\'s aliases — longer phrases outrank a hub, so be specific rather than numerous'
  );
});

test('asked_as never reaches the model or the row', () => {
  // It is authoring metadata. The claim lock passes seven whitelisted fields and this is
  // not one of them; `projectEntry` does not carry it, so no column is needed either.
  // Both are true by omission today, which is exactly the kind of thing that stops being
  // true silently.
  const card = projectEntry(entries[0], { doLine: 'Read the panel.' });
  assert.equal(card.asked_as, undefined, 'asked_as must not be projected onto the card');
  assert.equal('asked_as' in card, false, 'asked_as must not appear as a key at all');
});

/* ═════════ The strawberry boundary — one card since IC-3a ═════════

   RULED 2026-08-18: a bare `strawberries` is a shopper choosing which box to buy. That
   ruling sent the bare noun to a separate residue card and left freshness on
   `berries_picking`, with one deliberate tie ("fresh strawberries") broken on corpus order.

   FOLDED 2026-10-14 (IC-3a, docs/ITEM-CARDS-PLAN.md D3: one card per item): the residue
   card folded into `berries_picking`, retitled "Berries", so residue and freshness live on
   one card. The boundary is now one card: the bare noun and every freshness phrasing land
   on `berries_picking`, and the "fresh strawberries" tie is gone. The header's
   `gen_strawberry_freshness_check` incident stays closed because that card owns the noun. */

const boundary = (q) => scoreEntries(q, 3)[0]?.entry.id ?? null;

test('a bare strawberry row asks which box to buy, not whether it is fresh', () => {
  for (const q of ['strawberries', 'strawberry', '1 lb strawberries', 'organic strawberries']) {
    assert.equal(boundary(q), 'berries_picking', `"${q}" should reach the berries card`);
  }
  for (const q of ['driscoll', 'driscolls', 'driscolls strawberries']) {
    assert.equal(boundary(q), 'berries_picking', `"${q}" should reach the berries card`);
  }
});

test('the freshness question still reaches berries_picking after the reversal', () => {
  for (const q of [
    'how do i pick strawberries',
    'are these strawberries fresh',
    'moldy strawberries',
    'fresh strawberries',
    'strawberry freshness',
    'clamshell strawberries',
    'picking berries',
  ]) {
    assert.equal(boundary(q), 'berries_picking', `"${q}" is a freshness question and must stay on the picking card`);
  }
});

test('the reversal is scoped to strawberries and leaves the other berries alone', () => {
  // The residue card's evidence is strawberries. Routing a bare `berries` to it would hand
  // a blueberry question a strawberry answer, which is the hub rule running backwards.
  for (const q of ['berries', 'blueberries', 'raspberries', 'blackberries']) {
    assert.equal(boundary(q), 'berries_picking', `"${q}" is not in the strawberry ruling's scope`);
  }
});

test('chf-5 folds: every retired asked_as lands where measured (null = gate admits nothing)', () => {
  // All 15 asked_as of the 5 retired cards, from the KB before the fold. A landing is a card
  // for the same food subject; the subject card answering a cooking ask is corpus-wide
  // behaviour (no cooking veto on the ask door), not a chf-5 steal.
  const asks = [
    ['when should i salt a steak', 'beef_cuts_basics'],
    ['is a brine worth it', null],
    ['should i salt meat ahead', null],
    ['do salted beans go tough', 'beans_dried_vs_canned'],
    ['should i salt the bean soak', 'beans_dried_vs_canned'],
    ['does salt make beans hard', 'beans_dried_vs_canned'],
    ['how do you choose pretzel bread', null],
    ['what does lye dipped mean on pretzel rolls', null],
    ['what gives pretzel bread its brown crust', null],
    ['which baking powder should i buy', null],
    ['is bicarbonate of soda worth buying', null],
    ['how do i pick a baking powder', null],
    ['how do you choose duck breast', null],
    ['how long does a whole duck keep', null],
    ['how do you buy duck legs', 'chicken_cuts_basics'],
  ];
  for (const [q, want] of nonEmpty(asks, 'chf-5 retired asks', 15)) {
    assert.equal(inScope(q).ok, true, `"${q}" refused by the scope gate`);
    const top = scoreEntries(q, 3)[0];
    assert.equal(admits(top) ? top.entry.id : null, want, `"${q}" -> ${admits(top) ? top.entry.id : 'miss'}`);
  }
  // The can still answers its own row.
  const can = scoreEntries('canned coconut milk', 3)[0];
  assert.ok(admits(can), '"canned coconut milk" not admitted');
  assert.equal(can.entry.id, 'canned_coconut_milk');
});

