test('C5 changed copy has no forbidden brands, claims, prices or punctuation',t=>{
 const skip=new Set(['sources','aliases','asked_as','id','category','evidence_tier']);
 const brand=/whole foods|tyson|perdue|hormel|oscar mayer|applegate|boar.s head|smithfield|jimmy dean|hillshire|butterball|jennie-o|foster farms/i;
 const claim=/healthier|healthiest|better for you|lowers|exposure|protein|calorie/i;
 const price=/\\bcheapest\\b|\\bprice\\b|\\"'$[0-9]/i;
 const strings=v=>typeof v==='"'string'?[v]:Array.isArray(v)?v.flatMap(strings):v&&typeof v==='object'?Object.values(v).flatMap(strings):[];
 let count=0;
 for(const {id,field,value} of changed){
  if(skip.has(field))continue;count++;
  for(const s of strings(value))for(const re of [brand,claim,price,/—/,/\\b(I|me|my|mine|we|us|our)\\b/,/['\"]/])assert.doesNotMatch(s,re,id+'.'+field);
 }
